CREATE TEMP TABLE ctx06_test_results(case_name text PRIMARY KEY,passed boolean) ON COMMIT DROP;
DO $test$
DECLARE v jsonb:='{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","cohort_sha256":"2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec","membership_acceptance_sha256":"20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9","membership_view_sha256":"cb8b21066316568455e4c943190f339b9936bed9ced5532475369501bb4dbb86","calendar_sha256":"2489051535c8169bc836f8ab216c32c3ad68ad8e517f00f135186e74723e81d2","run_key":"a8b5b252d10b2a64bbe768ac7e9a51b013ecffa5600a948e3a86fa6b67598ba3","producer_output_sha256":"1e716860bc803d236c4516d77b9c7e78f3c9721735768b3ad4c7de734ce59b41","source_manifest_sha256":"6fc1aa93cf37e71830fb772b397bd4d6be85de7fc223f2551090c7377a4de2b9","vote_manifest_sha256":"bb8862f531e435aae4a16bedf14135e01de09e141e7c3a74e46b250081767953","aug03_manifest_sha256":"767e00eadd92ae007eb7865043720a48c8d3c7861442dfe843d21615ad842187","correction_manifest_sha256":"82f0311ae76e6b44ef3b72756c2266fa49de8ef4746daf1252f9a990ebf882da","summary_manifest_sha256":"1e716860bc803d236c4516d77b9c7e78f3c9721735768b3ad4c7de734ce59b41"}'::jsonb;r jsonb; k text; rejected boolean;
BEGIN
 r:=population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(v);
 INSERT INTO ctx06_test_results VALUES('actual_126000_plus_3000_integrity',(r->'structural_integrity_pass'='true'::jsonb)),('actual_43_correction_affected_cells',(r->>'correction_affected_vote_cells'='43')),('honest_qualification_hold',(r->'family_accepted'='false'::jsonb AND r->>'aug03_adjustment_qualified_rows'='0' AND r->'source_values_reverified_by_this_report'='false'::jsonb));
 INSERT INTO ctx06_test_results VALUES('deterministic',r=population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(v));
 FOREACH k IN ARRAY ARRAY['scope_sha256','cohort_sha256','membership_acceptance_sha256','membership_view_sha256','calendar_sha256','producer_output_sha256','source_manifest_sha256','run_key','vote_manifest_sha256','aug03_manifest_sha256','summary_manifest_sha256','correction_manifest_sha256'] LOOP
 rejected:=false;
 BEGIN PERFORM population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(v||jsonb_build_object(k,'changed')); EXCEPTION WHEN SQLSTATE 'P0001' THEN rejected:=SQLERRM IN('CTX06_CURRENT_INPUT_PIN_OR_PREDECESSOR_MISMATCH','CTX06_OUTPUT_MANIFEST_CHANGED'); END;
 INSERT INTO ctx06_test_results VALUES('reject_changed_'||k,rejected);
 END LOOP;
 FOREACH k IN ARRAY ARRAY['null','{}','[]'] LOOP
 rejected:=false; BEGIN PERFORM population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(k::jsonb); EXCEPTION WHEN SQLSTATE 'P0001' THEN rejected:=true;END;
 INSERT INTO ctx06_test_results VALUES('reject_shape_'||k,rejected);
 END LOOP;
 INSERT INTO ctx06_test_results SELECT 'private_invoker',NOT p.prosecdef AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') FROM pg_proc p WHERE p.oid='population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(jsonb)'::regprocedure;
 IF EXISTS(SELECT 1 FROM ctx06_test_results WHERE passed IS DISTINCT FROM true) THEN RAISE EXCEPTION 'TEST_FAILED:%',(SELECT jsonb_agg(t) FROM ctx06_test_results t);END IF;
END $test$;
SELECT jsonb_build_object('tests',(SELECT jsonb_agg(t ORDER BY case_name) FROM ctx06_test_results t),'passed',(SELECT count(*) FROM ctx06_test_results WHERE passed),'function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(jsonb)'::regprocedure),'UTF8')),'hex')) proof;

