CREATE TEMP TABLE native_results(name text,passed boolean,detail jsonb) ON COMMIT DROP;
DO $test$
DECLARE tid uuid:=gen_random_uuid();aid uuid:=gen_random_uuid();vid uuid;vaid uuid:=gen_random_uuid();iv jsonb;pk text;sha text;r jsonb;f jsonb;msg text;kind text;
BEGIN
 iv:=jsonb_build_object('report_inputs','{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","cohort_sha256":"2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec","membership_acceptance_sha256":"20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9","membership_view_sha256":"cb8b21066316568455e4c943190f339b9936bed9ced5532475369501bb4dbb86","calendar_sha256":"2489051535c8169bc836f8ab216c32c3ad68ad8e517f00f135186e74723e81d2","run_key":"a8b5b252d10b2a64bbe768ac7e9a51b013ecffa5600a948e3a86fa6b67598ba3","producer_output_sha256":"1e716860bc803d236c4516d77b9c7e78f3c9721735768b3ad4c7de734ce59b41","source_manifest_sha256":"6fc1aa93cf37e71830fb772b397bd4d6be85de7fc223f2551090c7377a4de2b9","vote_manifest_sha256":"bb8862f531e435aae4a16bedf14135e01de09e141e7c3a74e46b250081767953","aug03_manifest_sha256":"767e00eadd92ae007eb7865043720a48c8d3c7861442dfe843d21615ad842187","correction_manifest_sha256":"82f0311ae76e6b44ef3b72756c2266fa49de8ef4746daf1252f9a990ebf882da","summary_manifest_sha256":"1e716860bc803d236c4516d77b9c7e78f3c9721735768b3ad4c7de734ce59b41"}'::jsonb,'report_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(jsonb)'::regprocedure),'UTF8')),'hex'));
 pk:='ctx06-current-evidence-v1:'||encode(sha256(convert_to(iv::text,'UTF8')),'hex');
 sha:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(uuid,text)'::regprocedure),'UTF8')),'hex');
 INSERT INTO population_top3000_202608_202609_v1.pipeline_adapter(family_id,stage,function_oid,function_sha256,resource_class,enabled,reviewed_test_evidence,producer_revision,expected_batch_seconds)
 SELECT 'CTX06',s,'population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(uuid,text)'::regprocedure,sha,'DATABASE',true,'{"rollback_fixture":true,"independent_review":false}'::jsonb,'ROLLBACK_CANDIDATE_ONLY',8 FROM unnest(ARRAY['DERIVE','VALIDATE'])s;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_task(task_id,operation_key,family_id,stage,partition_key,payload,input_versions,status,attempt_id,lease_until,owner_fence,stop_generation) VALUES(tid,'rollback-ctx06-current:'||tid,'CTX06','DERIVE',pk,'{"kind":"CTX06_CURRENT_EVIDENCE_V1"}',iv,'LEASED',aid,clock_timestamp()+interval '3 minutes',3,1);
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) VALUES(aid,tid,1,encode(sha256(convert_to('rollback-only-token','UTF8')),'hex'),3,1,sha);
 FOREACH kind IN ARRAY ARRAY['wrong_token','stop','stale_fence','expired_lease','adapter_hash','input_revision','wrong_route'] LOOP
 BEGIN
 CASE kind
 WHEN 'stop' THEN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true;
 WHEN 'stale_fence' THEN UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET owner_fence=2 WHERE attempt_id=aid;
 WHEN 'expired_lease' THEN UPDATE population_top3000_202608_202609_v1.pipeline_task SET lease_until=clock_timestamp()-interval '1second' WHERE task_id=tid;
 WHEN 'adapter_hash' THEN UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET adapter_sha256='bad' WHERE attempt_id=aid;
 WHEN 'input_revision' THEN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions='{}' WHERE task_id=tid;
 WHEN 'wrong_route' THEN UPDATE population_top3000_202608_202609_v1.pipeline_task SET payload='{}' WHERE task_id=tid;
 ELSE NULL; END CASE;
 r:=population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(aid,CASE WHEN kind='wrong_token' THEN 'wrong' ELSE 'rollback-only-token' END);
 RAISE EXCEPTION 'TEST_UNEXPECTED_SUCCESS';
 EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS msg=MESSAGE_TEXT;
 INSERT INTO native_results VALUES(kind,msg=CASE kind WHEN 'wrong_token' THEN 'ATTEMPT_AUTH_FAILED' WHEN 'stop' THEN 'MISSION_HELD_OR_ADMISSION_EXPIRED' WHEN 'stale_fence' THEN 'STALE_OWNER_OR_STOP' WHEN 'expired_lease' THEN 'LEASE_LOST' WHEN 'adapter_hash' THEN 'ADAPTER_CODE_CHANGED' ELSE 'CTX06_CURRENT_REPORT_ROUTE_OR_CODE_MISMATCH' END,jsonb_build_object('error',msg));
 END;
 END LOOP;
 r:=population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(aid,'rollback-only-token');
 INSERT INTO native_results VALUES('derive_report',r->>'state'='COMPLETE' AND r->'family_accepted'='false'::jsonb,r);
 INSERT INTO native_results VALUES('idempotent_derive_report',r=population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(aid,'rollback-only-token'),'{}');
 f:=population_top3000_202608_202609_v1.pipeline_finish_v1(aid,'rollback-only-token',r);vid:=(f->>'successor_task_id')::uuid;
 INSERT INTO native_results VALUES('actual_commit_automatic_validate',f->>'state'='COMPLETE' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_commit WHERE task_id=tid) AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=vid AND stage='VALIDATE' AND input_versions=iv),f);
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=vaid,lease_until=clock_timestamp()+interval '3 minutes',owner_fence=3,stop_generation=1 WHERE task_id=vid;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) VALUES(vaid,vid,1,encode(sha256(convert_to('rollback-only-token','UTF8')),'hex'),3,1,sha);
 BEGIN
 DELETE FROM population_top3000_202608_202609_v1.pipeline_dependency WHERE task_id=vid;
 r:=population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(vaid,'rollback-only-token');
 RAISE EXCEPTION 'TEST_UNEXPECTED_SUCCESS';
 EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS msg=MESSAGE_TEXT;
 INSERT INTO native_results VALUES('missing_predecessor_rejected',msg='CTX06_CURRENT_REPORT_COMPLETED_PREDECESSOR_REQUIRED',jsonb_build_object('error',msg));
 END;
 r:=population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(vaid,'rollback-only-token');
 INSERT INTO native_results VALUES('actual_validate_honest_hold',r->>'state'='BLOCKED' AND r->>'blocker_code'='CTX06_CURRENT_SOURCE_ACTION_TEMPORAL_QUALIFICATION_REQUIRED' AND r#>>'{resumption_condition,correction_affected_vote_cells}'='43',r);
 f:=population_top3000_202608_202609_v1.pipeline_finish_v1(vaid,'rollback-only-token',r);
 INSERT INTO native_results VALUES('actual_hold_persisted',EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=vid AND status='BLOCKED' AND blocker_code='CTX06_CURRENT_SOURCE_ACTION_TEMPORAL_QUALIFICATION_REQUIRED'),f);
 INSERT INTO native_results SELECT 'private_invoker',NOT p.prosecdef AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE'),'{}' FROM pg_proc p WHERE p.oid='population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(uuid,text)'::regprocedure;
 IF EXISTS(SELECT 1 FROM native_results WHERE passed IS DISTINCT FROM true) THEN RAISE EXCEPTION 'NATIVE_PROOF_FAILED:%',(SELECT jsonb_agg(to_jsonb(n)) FROM native_results n);END IF;
END $test$;
SELECT jsonb_build_object('tests',count(*),'passed',count(*) FILTER(WHERE passed),'cases',jsonb_agg(to_jsonb(n)),'report_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(jsonb)'::regprocedure),'UTF8')),'hex'),'stage_function_sha256',encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(uuid,text)'::regprocedure),'UTF8')),'hex')) proof FROM native_results n;

