CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(p_attempt uuid,p_token text)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path TO pg_catalog AS $stage$
DECLARE tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;r jsonb;h text;eid bigint;prior jsonb;
BEGIN
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid;
 IF t.family_id IS DISTINCT FROM 'CTX06' OR t.stage NOT IN('DERIVE','VALIDATE') OR t.payload->>'kind' IS DISTINCT FROM 'CTX06_CURRENT_EVIDENCE_V1'
 OR t.partition_key IS DISTINCT FROM 'ctx06-current-evidence-v1:'||encode(sha256(convert_to(t.input_versions::text,'UTF8')),'hex')
 OR t.input_versions->>'report_function_sha256' IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(jsonb)'::regprocedure),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'CTX06_CURRENT_REPORT_ROUTE_OR_CODE_MISMATCH';END IF;
 r:=population_top3000_202608_202609_v1.ctx06_current_evidence_report_v1(t.input_versions->'report_inputs');
 IF r->'structural_integrity_pass' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'CTX06_CURRENT_REPORT_INTEGRITY_FAILED';END IF;
 h:=encode(sha256(convert_to(r::text,'UTF8')),'hex');
 SELECT event_id,details INTO eid,prior FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CTX06_CURRENT_EVIDENCE_REPORT_V1' AND details->>'partition_key'=t.partition_key ORDER BY event_id LIMIT 1;
 IF t.stage='DERIVE' THEN
  IF eid IS NULL THEN
   INSERT INTO population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details) VALUES(tid,p_attempt,'CTX06_CURRENT_EVIDENCE_REPORT_V1',jsonb_build_object('partition_key',t.partition_key,'input_versions',t.input_versions,'report',r,'report_sha256',h)) RETURNING event_id INTO eid;
  ELSIF prior->>'report_sha256' IS DISTINCT FROM h OR prior->'report' IS DISTINCT FROM r OR prior->'input_versions' IS DISTINCT FROM t.input_versions THEN RAISE EXCEPTION 'CTX06_CURRENT_REPORT_REPLAY_CONFLICT';END IF;
  RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','ctx06-current-report:'||t.partition_key,'input_versions',t.input_versions,'immutable_output_ids',jsonb_build_array(eid),'output_sha256',h,'new_committed_units',1),'family_accepted',false);
 END IF;
 IF eid IS NULL OR prior->>'report_sha256' IS DISTINCT FROM h OR prior->'report' IS DISTINCT FROM r OR prior->'input_versions' IS DISTINCT FROM t.input_versions OR NOT EXISTS(
 SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task p JOIN population_top3000_202608_202609_v1.pipeline_commit c ON c.task_id=p.task_id
 WHERE p.task_id=(t.payload->>'parent_task_id')::uuid AND p.family_id='CTX06' AND p.stage='DERIVE' AND p.status='COMPLETE' AND p.input_versions=t.input_versions AND p.partition_key=t.partition_key)
 THEN RAISE EXCEPTION 'CTX06_CURRENT_REPORT_COMPLETED_PREDECESSOR_REQUIRED';END IF;
 RETURN jsonb_build_object('state','BLOCKED','blocker_code','CTX06_CURRENT_SOURCE_ACTION_TEMPORAL_QUALIFICATION_REQUIRED',
 'resumption_condition',jsonb_build_object('report_event_id',eid,'report_sha256',h,'required_checks',r->'required_remaining_qualification','correction_affected_vote_cells',r->'correction_affected_vote_cells','supported_next_action','VERSIONED_EXACT_CORRECTION_RECOMPUTATION_AND_SOURCE_ACTION_SESSION_QUALIFICATION','source_coverage_unknown_remains_unknown',true,'automatic_retry_without_new_evidence',false),'family_accepted',false);
END $stage$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.ctx06_current_evidence_stage_v1(uuid,text) FROM PUBLIC,anon,authenticated;
